// SetSearchIndexesEnabled controls the experimental search-index feature for
// this server and its stores. It defaults to false.
func (s *Server) SetSearchIndexesEnabled(enabled bool) {
	if s == nil {
		return
	}
	s.searchIndexesEnabled.Store(enabled)
	if s.StoreManager != nil {
		s.StoreManager.EnableSearchIndexes(enabled)
	}
}

func (s *Server) configureSearchBranch(branch *core.Branch) {
	if s == nil || branch == nil {
		return
	}
	branch.SetSearchIndexesEnabled(s.searchIndexesEnabled.Load())
	s.searchEmbedderMu.RLock()
	embedder := s.searchEmbedder
	s.searchEmbedderMu.RUnlock()
	if embedder != nil {
		branch.SetSearchEmbedder(embedder)
	}
}

func (s *Server) SetDefaultQueryTimeout(timeout time.Duration) {
	if timeout < 0 {
		timeout = 0
	}
	s.DefaultQueryTimeout = timeout
}

// SetSPARQLResourceConfig configures node, store, and query limits for SPARQL
// reads. Existing query leases retain their query-specific ceilings while new
// reservations immediately observe updated node and store limits.
func (s *Server) SetSPARQLResourceConfig(config sparql.ResourceConfig) {
	if s == nil {
		return
	}
	if s.sparqlResources == nil {
		s.sparqlResources = sparql.NewResourceManager(config)
		return
	}
	s.sparqlResources.SetConfig(config)
}

// SetSPARQLStoreResourcePolicy overrides concurrency, memory, and spill policy
// for one immutable store identity.
func (s *Server) SetSPARQLStoreResourcePolicy(storeID string, policy sparql.StoreResourcePolicy) {
	if s == nil || s.sparqlResources == nil {
		return
	}
	s.sparqlResources.SetStorePolicy(storeID, policy)
}

// SPARQLResourceSnapshot returns current resource usage for diagnostics.
func (s *Server) SPARQLResourceSnapshot() sparql.ResourceSnapshot {
	if s == nil || s.sparqlResources == nil {
		return sparql.ResourceSnapshot{}
	}
	return s.sparqlResources.Snapshot()
}

// routes sets up the routes for the server
func (s *Server) routes() {
	// serve the static web UI
	s.Echo.File("/", "web/static/index.html")
	s.Echo.Static("/", "web/static")

	s.Echo.GET("/health", s.healthHandler)
	s.Echo.GET("/healthz", s.healthHandler) // alias for the proxy/orchestrator's /healthz convention
	s.Echo.GET("/ready", s.readyHandler)

	s.Echo.POST("/stores/:store/query", s.queryHandler)
	s.Echo.GET("/stores/:store/sparql", s.sparqlGetHandler)
	s.Echo.POST("/stores/:store/talk", s.talkHandler)
	s.Echo.POST("/stores/:store/ontology/plan", s.ontologyPlanHandler)
	s.Echo.POST("/stores/:store/ontology/apply", s.ontologyApplyHandler)
	s.Echo.POST("/stores/:store/computed/reload", s.computedReloadHandler)
	s.Echo.POST("/stores/:store/computed/run", s.computedRunHandler)
	s.Echo.POST("/stores/:store/update_with_invariant", s.sparqlUpdateWithInvariantHandler)
	s.Echo.POST("/stores/:store/validate", s.validateHandler)
	s.Echo.GET("/stores/:store/search-index", s.getSearchIndexHandler)
	s.Echo.PUT("/stores/:store/search-index", s.configureSearchIndexHandler)
	s.Echo.POST("/stores/:store/search-index/catchup", s.catchUpSearchIndexHandler)

	s.Echo.POST("/stores/:store/import", s.importHandler)
	s.Echo.POST("/stores/:store/import/stage", s.stageUploadHandler)
	s.Echo.POST("/stores/:store/historical-import", s.historicalImportHandler)
	// Job status is store-scoped: a job's record is node-local in-memory state
	// on the node that ran the operation. The routing proxy pins these to the
	// store's primary (consistency=primary).
	s.Echo.GET("/stores/:store/jobs", s.listStoreJobsHandler)
	s.Echo.GET("/stores/:store/jobs/:id", s.getStoreJobHandler)
	s.Echo.POST("/stores/:store/export", s.exportHandler)
	s.Echo.GET("/stores/:store/graphs", s.listGraphsHandler)
	s.Echo.PUT("/stores/:store/graphs", s.graphStorePutHandler)
	s.Echo.POST("/stores/:store/graphs", s.graphStorePostHandler)
	s.Echo.DELETE("/stores/:store/graphs", s.deleteGraphHandler)
	s.Echo.GET("/stores/:store/snapshots", s.listSnapshotsHandler)
	s.Echo.GET("/stores/:store/snapshots/:snapshot_id", s.getSnapshotHandler)
	s.Echo.PUT("/stores/:store/snapshots/:snapshot_id/metadata", s.replaceSnapshotMetadataHandler)
	s.Echo.POST("/stores/:store/update", s.updateHandler)
	s.Echo.POST("/stores/:store/checkpoint", s.checkpointHandler)
	// Store-scoped maintenance op. Lives under /stores/:store/* so the routing
	// proxy's generic /stores/:store/* route forwards it to the store's primary
	// (a POST is write-classed), letting clients force compaction through the
	// proxy without knowing which node is primary. Requires write access, like
	// the other store-scoped POSTs alongside it.
	s.Echo.POST("/stores/:store/compact", s.compactHandler)
	// Alongside compact and for the same reason: a POST under /stores/:store/* is
	// write-classed, so the proxy forwards it to the primary, which is the only node
	// that can hold maintenance authority for the store.
	s.Echo.POST("/stores/:store/reclaim", s.reclaimHandler)
	s.Echo.GET("/stores/:store/gremlin", s.gremlinWebSocketHandler)
	s.Echo.POST("/stores/:store/gremlin/groovy", s.gremlinGroovyHandler)

	// add routes for store management
	s.Echo.POST("/stores/:store", s.createStoreHandler)
	s.Echo.GET("/stores", s.listStoresHandler)
	s.Echo.DELETE("/stores/:store", s.deleteStoreHandler)
	s.Echo.POST("/stores/:store/loadalldata", s.loadAllDataHandler)

	// branch management
	s.Echo.POST("/stores/:store/branches/:source/merge/plan", s.branchMergePlanHandler)
	s.Echo.POST("/stores/:store/branches/:source/merge/apply", s.branchMergeApplyHandler)
	s.Echo.POST("/stores/:store/branches/:source/rebase/plan", s.branchRebasePlanHandler)
	s.Echo.POST("/stores/:store/branches/:source/rebase/apply", s.branchRebaseApplyHandler)
	s.Echo.GET("/stores/:store/diff", s.branchSnapshotDiffHandler)
	s.Echo.GET("/stores/:store/branches", s.listBranchesHandler)
	s.Echo.POST("/stores/:store/branches/:branch", s.createBranchHandler)
	s.Echo.DELETE("/stores/:store/branches/:branch", s.deleteBranchHandler)
	s.Echo.POST("/stores/:store/branches/:branch/promote", s.promoteBranchHandler)

	// application management — definitions are store-level data (names are
	// per-store), served under the store's own path. The cross-store
	// GET /applications aggregator was removed: definitions are always accessed
	// with their store in context (list per store below).
	s.Echo.POST("/stores/:store/applications/:appname", s.uploadApplicationHandler)
	s.Echo.GET("/stores/:store/applications", s.listStoreApplicationsHandler)
	s.Echo.GET("/stores/:store/applications/:appname", s.getApplicationHandler)
	s.Echo.DELETE("/stores/:store/applications/:appname", s.deleteApplicationHandler)

	// application data endpoints
	// Application data CRUD is store-scoped: an app projects classes over one
	// store's graph (app.Store), so the data endpoints live under the store and
	// ride normal store routing (reads → replica, writes → primary).
	s.Echo.GET("/stores/:store/apps/:app/:class", s.appListHandler)
	s.Echo.GET("/stores/:store/apps/:app/:class/:id", s.appGetHandler)
	s.Echo.POST("/stores/:store/apps/:app/:class/:id", s.appPostHandler)
	s.Echo.PUT("/stores/:store/apps/:app/:class/:id", s.appPutHandler)
	s.Echo.DELETE("/stores/:store/apps/:app/:class/:id", s.appDeleteHandler)

	s.registerSecurityRoutes()

	// add admin for version management and restart
	s.Echo.GET("/admin/version", s.getVersionHandler)
	s.Echo.POST("/admin/restart", s.restartHandler)
	s.Echo.POST("/admin/upgrade", s.upgradeHandler)

	// Store-lifecycle repair. Both are cluster-global (they read/write the shared
	// stores index and store prefixes) and reachable through the orchestrator's
	// /admin/* fronting, which prefers the system-store primary.
	s.Echo.GET("/admin/store-inventory", s.storeInventoryHandler)

	// What is holding this node's snapshots open. Node-local and read-only: it describes
	// this process's memory, so it is deliberately not fronted by the orchestrator.
	s.Echo.GET("/admin/open-transactions", s.openTransactionsHandler)
	s.Echo.POST("/admin/stores/purge", s.purgeStoresHandler)

	// get and set config
	// s.Echo.GET("/admin/config", s.getConfigHandler)
	// s.Echo.POST("/admin/config", s.setConfigHandler)

	// Internal cluster endpoints (node-to-node). These authenticate with the
	// shared cluster credential inside the handler and are exempted from the
	// JWT/ACL middleware (see isInternalClusterPath in middleware.go).
	s.Echo.POST(clusterBundleRoutePath, s.clusterBundleHandler)
	// GET .../bundles/:lsn lets a newly-promoted primary fetch a committed
	// bundle it is missing from a peer that still holds it (peer reconciliation,
	// web/bundle_reconcile.go) — the recovery path that keeps acked writes
	// held on a non-promoted replica from being lost.
	s.Echo.GET(clusterBundleFetchRoutePath, s.clusterBundleFetchHandler)
	// Store deletion releases the name first and reclaims the old GUID later.
	s.Echo.POST(clusterStoreReleaseRoutePath, s.clusterStoreReleaseHandler)
	s.Echo.POST(clusterStoreCreationBindingRoutePath, s.clusterStoreCreationBindingHandler)
	s.Echo.POST(clusterStorePrefixReclaimRoutePath, s.clusterStorePrefixReclaimHandler)
	s.Echo.GET(clusterStoreInventoryRoutePath, s.clusterStoreInventoryHandler)
	s.Echo.POST(clusterStorePurgeRoutePath, s.clusterStorePurgeHandler)
	s.Echo.POST(clusterStorePrefixFenceRoutePath, s.clusterStorePrefixFenceHandler)
	// Re-publishes an explicitly named name/GUID binding on the system chain.
	// REQUESTED, not inferred from tenant files; it must run on the system primary.
	s.Echo.POST(clusterStoreRecoverRoutePath, s.clusterStoreRecoverRegistrationHandler)
	// What this node holds locally for a store, assigned or not. The evidence the
	// frontier reconciliation needs before it can declare committed writes lost.
	s.Echo.GET(clusterStoreLocalStateRoutePath, s.clusterStoreLocalStateHandler)
	// The security document, including the cluster's one JWT signing keypair. Driven by
	// /cluster/reset on the orchestrator: no user could authenticate here once the nodes
	// have diverged on that key, which is the state it repairs.
	s.Echo.POST(clusterSecurityResetRoutePath, s.clusterSecurityResetHandler)
	s.Echo.POST(clusterServiceCacheReclaimRoutePath, s.clusterServiceCacheReclaimHandler)

	s.registerAgentRoutes()
}

