func (s *Server) sparqlResourceError(c echo.Context, err error) error {
	if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
		return s.queryContextError(c, err)
	}
	if sparql.IsResourceLimit(err) {
		if !c.Response().Committed {
			c.Response().Header().Set("Retry-After", "1")
			return c.JSON(http.StatusTooManyRequests, map[string]string{"error": err.Error()})
		}
	}
	return err
}

func (s *Server) queryContextError(c echo.Context, err error) error {
	if err == nil {
		return nil
	}
	if c.Response().Committed {
		return err
	}
	status := http.StatusGatewayTimeout
	message := err.Error()
	if errors.Is(err, context.DeadlineExceeded) {
		message = "query timed out"
	} else if errors.Is(err, context.Canceled) {
		message = "query canceled"
	}
	return c.JSON(status, map[string]string{"error": message})
}

func (s *Server) logQuery(c echo.Context, context, query string, start time.Time) {
	s.loggerForRequest(c).Info(fmt.Sprintf("Query: %s | Duration: %s", decodeQuery(query), time.Since(start)), context)
}

// queryHandler handles the query endpoint
func (s *Server) queryHandler(c echo.Context) error {
	s.loggerForRequest(c).Info("Received query request", "server.QueryHandler")

	// Get the query from the body
	query, err := io.ReadAll(c.Request().Body)
	if err != nil {
		s.loggerForRequest(c).Error("Failed to read request body", "server.QueryHandler", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read request body"})
	}

	contentType := c.Request().Header.Get("Content-Type")
