		s.loggerForRequest(c).Error("Failed to apply read security", "server.ExecuteSparqlQuery", err)
		return c.JSON(http.StatusInternalServerError, map[string]string{"error": err.Error()})
	}

	accept := c.Request().Header.Get("Accept")
	usePredicateStats, err := parseOptionalBoolQueryParamDefault(c, "optimizer_stats", true)
	if err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{"error": "invalid optimizer_stats value"})
	}
