		return c.JSON(http.StatusBadRequest, map[string]string{"error": "optimizer_trace requires JSON results"})
	}

	evaluator := &sparql.QueryEvaluator{
		Txn:                  txn,
		Graphs:               graphs,
		Resources:            lease,
		Logger:               s.loggerForRequest(c),
		EntailmentFacts:      entailFacts,
		UsePredicateStats:    usePredicateStats,
		EnableOptimizerTrace: enableOptimizerTrace,
	}

	if parsedQuery.DescribeClause != nil {
		tripleIter, err := evaluator.EvaluateDescribeQuery(parsedQuery)
		if err != nil {
			return s.sparqlEvaluationError(c, err)
		}
		if err := queryCtx.Err(); err != nil {
			return s.queryContextError(c, err)
		}
