				response["optimizer_trace"] = evaluator.OptimizerTrace()
			}
			body, contentType, err := traceJSONResponse("application/json; charset=utf-8", response)
			if err != nil {
				return err
			}
			return c.Blob(http.StatusOK, contentType, body)
		}

		c.Response().Header().Set(echo.HeaderContentType, "application/rdf+xml; charset=utf-8")
		c.Response().WriteHeader(http.StatusOK)
		if err := writeTriplesAsRDFXMLWithContext(queryCtx, c.Response(), tripleIter); err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				return s.queryContextError(c, err)
			}
			return err
		}
		if err := evaluator.RuntimeErr(); err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				return s.queryContextError(c, err)
			}
			return err
		}
		c.Response().Flush()
		return nil
	}

	if parsedQuery.ConstructClause != nil {
		tripleIter, err := evaluator.EvaluateConstructQuery(parsedQuery)
		if err != nil {
			return s.sparqlEvaluationError(c, err)
		}
		if err := queryCtx.Err(); err != nil {
			return s.queryContextError(c, err)
		}
		if enableOptimizerTrace || strings.Contains(accept, "application/json") {
			triples := make([]map[string]string, 0)
			for {
				if err := queryCtx.Err(); err != nil {
					return s.queryContextError(c, err)
				}
				tr, ok := tripleIter.Next()
				if !ok {
					if err := evaluator.RuntimeErr(); err != nil {
						if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
							return s.queryContextError(c, err)
						}
						return err
					}
					break
				}
				row, err := budgetedTripleJSON(lease, tr)
				if err != nil {
					return s.sparqlResourceError(c, err)
				}
				triples = append(triples, row)
			}
			response := map[string]any{
				"message": "SPARQL CONSTRUCT executed",
				"query":   query,
				"results": triples,
			}
			if enableOptimizerTrace {
				response["optimizer_trace"] = evaluator.OptimizerTrace()
			}
			body, contentType, err := traceJSONResponse("application/json; charset=utf-8", response)
			if err != nil {
				return err
			}
			return c.Blob(http.StatusOK, contentType, body)
		}

		c.Response().Header().Set(echo.HeaderContentType, "application/rdf+xml; charset=utf-8")
		c.Response().WriteHeader(http.StatusOK)
		if err := writeTriplesAsRDFXMLWithContext(queryCtx, c.Response(), tripleIter); err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
