			if err != nil {
				return err
			}
			return c.Blob(http.StatusOK, contentType, body)
		}
		c.Response().Header().Set(echo.HeaderContentType, "application/sparql-results+xml; charset=utf-8")
		c.Response().WriteHeader(http.StatusOK)
		if err := writeAskXMLResult(c.Response(), ok); err != nil {
