		body, contentType, err := traceJSONResponse("application/sparql-results+json; charset=utf-8", response)
		if err != nil {
			return err
		}
		return c.Blob(http.StatusOK, contentType, body)
	}

	if acceptsJSONResults(accept) {
		c.Response().Header().Set(echo.HeaderContentType, "application/sparql-results+json; charset=utf-8")
		c.Response().WriteHeader(http.StatusOK)

		vars := selectResultVarNames(parsedQuery.SelectClause)
		if err := sparql.WriteResultsJSON(queryCtx, c.Response(), vars, resultIter); err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				return s.queryContextError(c, err)
			}
			return err
		}
		// A runtime error can surface only after iteration ends; the body is
		// already (partially) written, so this is best-effort reporting.
		if err := evaluator.RuntimeErr(); err != nil {
			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
				return s.queryContextError(c, err)
			}
			return err
		}
		return nil
	}

	c.Response().Header().Set(echo.HeaderContentType, "application/sparql-results+xml; charset=utf-8")
	c.Response().WriteHeader(http.StatusOK)
	vars := selectResultVariables(parsedQuery.SelectClause)
	if err := writeSparqlXMLResultsWithContext(queryCtx, c.Response(), vars, resultIter); err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return s.queryContextError(c, err)
		}
		return err
	}
	if err := evaluator.RuntimeErr(); err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return s.queryContextError(c, err)
		}
		return err
	}
	c.Response().Flush()

	return nil
}

