// tell them apart from the status, so the server has to say which one it was.
func NewValidateJWTMiddleware(manager *security.Manager, logger core.Logger) echo.MiddlewareFunc {
	return func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c echo.Context) error {
			// allow unauthenticated health, readiness, and login requests.
			// /ready is the k8s readinessProbe endpoint (see
			// MULTINODE_TUTORIAL.md); the kubelet calls it without credentials,
			// so it must stay open even in secured mode, like /health.
			// /healthz is the same check under the proxy/orchestrator's path convention.
			if c.Path() == "/health" || c.Path() == "/healthz" || c.Path() == "/ready" || c.Path() == metricsPath || c.Path() == "/admin/authenticate/password" || c.Path() == "/admin/authenticate/jwt" {
				return next(c)
			}
			// internal cluster endpoints enforce their own auth
			if isInternalClusterPath(c.Path()) {
				return next(c)
			}
			if manager == nil {
				// Not a credentials problem at all: this node is running secured but has no
				// security manager, so it can never accept anyone. A configuration fault.
				logRejectedJWT(logger, c, "this node has no security manager, so no token can be verified here", nil)
				return echo.NewHTTPError(401, "Unauthorized")
			}

			// JWT token is expected to be in the Authorization header
			token := c.Request().Header.Get("Authorization")
			if token == "" {
				// The caller sent nothing. Debug, not warn: unauthenticated probes and
				// scanners hit this constantly, and drowning the interesting case below in
				// them is how the interesting case got missed.
				if logger != nil {
					logger.Debug(fmt.Sprintf("rejected %s %s: no Authorization header", c.Request().Method, c.Path()), "web.middleware.jwt")
				}
				return echo.NewHTTPError(401, "Unauthorized")
			}

			// remove bearer prefix
			token = strings.TrimPrefix(token, "Bearer ")

			username, err := manager.VerifyServiceJWT(token)
			if err != nil {
				// The one that matters. A token was presented and this node would not accept
				// it, and the reason distinguishes "the client's token is expired or
				// malformed" from "this node's signing key is not the one that minted it",
				// which is the shape of a cluster that has diverged and needs an operator
				// rather than a new password.
				logRejectedJWT(logger, c, "the presented token did not verify against this node's signing key", err)
				return echo.NewHTTPError(401, "Unauthorized")
			}

			// get the user from the claims and set it in the context
			c.Set("username", username)
			return next(c)
		}
	}
}

