func (acm *Manager) GenerateKeyPairForUser(username string) (string, string, error) {
	privateKey, publicKey, _, err := acm.GenerateKeyPairForUserVersioned(username, nil)
	return privateKey, publicKey, err
}

func (acm *Manager) GenerateKeyPairForUserVersioned(username string, expectedVersion *int64) (string, string, int64, error) {
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", "", 0, err
	}

	privateKeyPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: x509.MarshalPKCS1PrivateKey(privateKey),
	})

	publicKeyBytes, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
	if err != nil {
		return "", "", 0, err
	}

	publicKeyPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "PUBLIC KEY",
		Bytes: publicKeyBytes,
	})

	version, err := acm.mutate(expectedVersion, func() error {
		for _, user := range acm.Users {
			if user.Username == username {
				user.PublicKey = publicKeyPEM
				return nil
			}
		}
		return ErrUserNotFound
	})
	if err != nil {
		return "", "", 0, err
	}

	return string(privateKeyPEM), string(publicKeyPEM), version, nil
}

func (acm *Manager) AuthenticateWithPassword(username, password string) (string, error) {
	acm.lock.Lock()
	defer acm.lock.Unlock()
	acm.pullIfStaleLocked()

	if username == "admin" {
		err := bcrypt.CompareHashAndPassword(acm.AdminPassword, []byte(password))
		if err != nil {
			return "", errors.New("invalid password")
		}

		token, err := acm.generateJWTLocked(username)
		if err != nil {
			return "", err
		}

		return token, nil
	}

	// Re-reads the document once if the identity is unknown here, so a user provisioned
	// on the primary a moment ago authenticates without waiting for the next poll.
	user := acm.findUserLocked(username)
	if user == nil {
		return "", errors.New("user not found")
	}

	err := bcrypt.CompareHashAndPassword([]byte(user.Password), []byte(password))
	if err != nil {
		return "", errors.New("invalid password")
	}

