func (acm *Manager) AuthenticateWithPassword(username, password string) (string, error) {
	acm.lock.Lock()
	defer acm.lock.Unlock()
	acm.pullIfStaleLocked()

	if username == "admin" {
		err := bcrypt.CompareHashAndPassword(acm.AdminPassword, []byte(password))
		if err != nil {
			return "", errors.New("invalid password")
		}

		token, err := acm.generateJWTLocked(username)
		if err != nil {
			return "", err
		}

		return token, nil
	}

	// Re-reads the document once if the identity is unknown here, so a user provisioned
	// on the primary a moment ago authenticates without waiting for the next poll.
	user := acm.findUserLocked(username)
	if user == nil {
		return "", errors.New("user not found")
	}

	err := bcrypt.CompareHashAndPassword([]byte(user.Password), []byte(password))
	if err != nil {
		return "", errors.New("invalid password")
	}

