// listStoresHandler handles the list stores endpoint
func (s *Server) listStoresHandler(c echo.Context) error {
	s.loggerForRequest(c).Info("Received list stores request", "server.ListStoresHandler")

	if s.StoreManager.MultiNode {
		if err := s.StoreManager.ReloadStoreList(); err != nil {
			s.loggerForRequest(c).Error("Failed to reload store list", "server.ListStoresHandler", err)
			return c.JSON(http.StatusInternalServerError, map[string]string{"error": err.Error()})
		}
	}

	stores := s.StoreManager.ListStores()

	// need to filter the stores the user has access to
	if s.StoreManager.SecurityManager == nil {
		return c.JSON(http.StatusOK, stores)
	}

	if username, _ := c.Get("username").(string); username == "admin" {
		return c.JSON(http.StatusOK, stores)
	}

	visibleStores := stores[:0]
	for _, store := range stores {
		fullStorePath := "/stores/" + store
		if s.StoreManager.SecurityManager.CheckAccess(c.Get("username").(string), fullStorePath, security.Read) {
			visibleStores = append(visibleStores, store)
		}
	}

	return c.JSON(http.StatusOK, visibleStores)
}

